import { loadFont } from "@remotion/google-fonts/Arimo";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// BLACK FALCON v3: no "Mas corre!" entra a esteira (IMG_0456, public/josiane/b3), a pedido da cliente, que reenviou os três vídeos.
// BLACK FALCON v2: os três clipes agora são os vídeos que a cliente mandou (salão de musculação IMG_0457 e fachada
// IMG_0478, em public/josiane/b1 e b2); o resto é a v1. Na fachada o logo de cima sai, porque o letreiro já aparece.
// BLACK FALCON (Academia Falcon, cliente Josiane) — última chance do plano anual de musculação, 20/11. Jeito motion: não
// veio foto nem vídeo, então o vídeo é tipografia, preço, barras de comparação e calendário, com três clipes curtos de
// musculação da própria academia (do vídeo da TV) como respiro. Identidade da Falcon: preto, vermelho e branco, Arimo
// itálico caixa-alta, palavra-chave em tarja branca inclinada. Tempos = voz src/voz-black-v2.mp3 (o locutor), começa em 0.

const { fontFamily: FI } = loadFont("italic", { weights: ["700"], subsets: ["latin", "latin-ext"] });

export const FB3_FPS = 30;
const END = 28.7;
export const FB3_FRAMES = Math.round(END * FB3_FPS);
const RED = "#D4000F";
const DARK_RED = "#5C0009";
const WHITE = "#FFFFFF";
const INK = "#0B0B0B";
const PAPER = "#F3F1EE";
const COL = 840;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.3));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const it = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: FI, fontStyle: "italic", fontWeight: 700, fontSize: size, lineHeight: 1, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.01em" });
const slam = (t: number, at: number, d = 0.28): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.7 - 0.7 * e).toFixed(3)})` };
};

// cenas desenhadas; fora delas aparece um clipe da academia
const MS = { hook: [0, 2.0], brand: [2.0, 3.72], price: [5.1, 7.68], cmp: [7.68, 14.72], eco: [14.72, 18.08], date: [19.95, 21.38], fim: [23.9, END] } as const;
const inM = (t: number) => Object.values(MS).some(([a, b]) => t >= a && t < b);
type Seg = { a: number; b: number; src: string; from: number; zin?: boolean; punch?: boolean };
const SEGS: Seg[] = [
  { a: 3.72, b: 5.1, src: "b1", from: 0.2, zin: true },
  { a: 18.08, b: 19.95, src: "b3", from: 0.3, punch: true },
  { a: 21.38, b: 23.9, src: "b2", from: 1.0 },
];

const Clip: React.FC<{ t: number; s: Seg }> = ({ t, s }) => {
  if (t < s.a - 0.01 || t > s.b + 0.3) return null;
  const u = lin(t, s.a, s.b + 0.3);
  const z = (s.zin ? 1.04 + 0.1 * u : 1.15 - 0.09 * u) * (s.punch ? 1 + 0.25 * (1 - k(t, s.a, 0.3)) : 1);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: "#000" }}>
      <Sequence from={Math.round(s.a * FB3_FPS)} layout="none">
        <OffthreadVideo src={staticFile(`josiane/${s.src}.mp4`)} trimBefore={Math.round(s.from * FB3_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z.toFixed(4)})` }} />
      </Sequence>
    </AbsoluteFill>
  );
};

// ───────── lettering sobre os clipes: cada frase no mesmo lugar ─────────
type Ln = { w: string; at: number; tag?: boolean; size?: number };
const PH: { lines: Ln[]; out: number }[] = [
  { lines: [{ w: "Plano anual de", at: 3.78 }, { w: "Musculação", at: 4.36, tag: true }], out: 4.95 },
  { lines: [{ w: "Mas", at: 18.12 }, { w: "Corre!", at: 18.36, tag: true, size: 130 }], out: 19.75 },
  { lines: [{ w: "Aula experimental", at: 21.58 }, { w: "Grátis!", at: 23.06, tag: true, size: 130 }], out: 23.75 },
];
const fit = (l: Ln) => l.size ?? Math.min(l.tag ? 112 : 76, Math.floor((COL - (l.tag ? 80 : 0)) / (l.w.length * (l.tag ? 0.6 : 0.56))));

const Tag: React.FC<{ t: number; at: number; w: string; size: number; shadow?: string; bg?: string; fg?: string }> = ({ t, at, w, size, shadow = RED, bg = WHITE, fg = RED }) => (
  <div style={{ background: bg, padding: `${size * 0.12}px ${size * 0.36}px ${size * 0.18}px`, transform: `skewX(-10deg) scaleX(${k(t, at, 0.42).toFixed(3)})`, boxShadow: `0 16px 40px rgba(0,0,0,0.35), 12px 12px 0 ${shadow}` }}>
    <div style={{ ...it(size, fg), transform: "skewX(10deg)", opacity: interpolate(t, [at + 0.08, at + 0.36], [0, 1], { ...cl, easing: OUT }) }}>{w}</div>
  </div>
);
const Line: React.FC<{ t: number; at: number; w: string; size: number; color?: string; shadow?: boolean }> = ({ t, at, w, size, color = WHITE, shadow = true }) => {
  const e = k(t, at, 0.4);
  // entra subindo de trás de uma linha (máscara) e para
  return (
    <div style={{ overflow: "hidden", padding: "6px 14px 10px" }}>
      <div style={{ ...it(size, color), textShadow: shadow ? "0 4px 18px rgba(0,0,0,0.45)" : "none", transform: `translateY(${((1 - e) * 110).toFixed(1)}%)` }}>{w}</div>
    </div>
  );
};

const Lettering: React.FC<{ t: number }> = ({ t }) => (
  <>
    {PH.map((p, i) => {
      if (t < p.lines[0].at - 0.02 || t > p.out + 0.18) return null;
      const o = lin(t, p.out, p.out + 0.16);
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 1290, height: 340, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, opacity: 1 - o }}>
          {p.lines.map((l, j) => (l.tag ? <Tag key={j} t={t} at={l.at} w={l.w} size={fit(l)} /> : <Line key={j} t={t} at={l.at} w={l.w} size={fit(l)} />))}
        </div>
      );
    })}
  </>
);

// ───────── fundos lisos ─────────
const DarkBg: React.FC<{ t: number }> = ({ t }) => {
  const d = Math.sin(t * 0.5) * 40;
  return (
    <AbsoluteFill style={{ background: "linear-gradient(170deg, #0A0A0A 0%, #110508 60%, #24000A 100%)", overflow: "hidden" }}>
      {[[780, 230, RED, 0.9], [560, 90, DARK_RED, 0.8], [-160, 160, DARK_RED, 0.5]].map(([x, w, col, op], i) => (
        <div key={i} style={{ position: "absolute", left: (x as number) + d * (i % 2 ? 1 : -1), top: -300, width: w as number, height: 2600, background: col as string, opacity: op as number, transform: "skewX(-24deg)" }} />
      ))}
    </AbsoluteFill>
  );
};
const RedBg: React.FC = () => (
  <AbsoluteFill style={{ background: `linear-gradient(165deg, #F01020 0%, ${RED} 45%, #7A0008 100%)` }} />
);
const PaperBg: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 90% 60% at 50% 40%, #FFFFFF 0%, ${PAPER} 60%, #E2DDD8 100%)` }} />;

type Cam = "in" | "out" | "left" | "right" | "tilt" | "none";
const MScene: React.FC<{ t: number; a: number; b: number; bg: "dark" | "red" | "paper" | "black"; cam: Cam; children: React.ReactNode }> = ({ t, a, b, bg, cam, children }) => {
  if (t < a || t >= b) return null;
  const e = interpolate(lin(t, a, b), [0, 1], [0, 1], { easing: Easing.inOut(Easing.sin) });
  const enter = 1 - k(t, a, 0.5); // a cena já entra em movimento
  const tr =
    cam === "in" ? `scale(${(1 + 0.12 * e + 0.06 * enter).toFixed(4)})`
    : cam === "out" ? `scale(${(1.14 - 0.12 * e).toFixed(4)})`
    : cam === "left" ? `translateX(${(60 - 120 * e + 80 * enter).toFixed(1)}px) scale(1.07)`
    : cam === "right" ? `translateX(${(-40 + 80 * e - 80 * enter).toFixed(1)}px) scale(${(1.02 + 0.07 * e).toFixed(4)})`
    : cam === "tilt" ? `rotate(${(-2 + 4 * e).toFixed(2)}deg) scale(${(1.05 + 0.06 * e).toFixed(4)})`
    : `translateY(${(90 * enter).toFixed(1)}px)`;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {bg === "dark" ? <DarkBg t={t} /> : bg === "red" ? <RedBg /> : bg === "paper" ? <PaperBg /> : <AbsoluteFill style={{ background: "radial-gradient(ellipse 80% 55% at 50% 45%, #1C1C1C 0%, #050505 75%)" }} />}
      <AbsoluteFill style={{ transform: tr, transformOrigin: "50% 45%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const Row: React.FC<{ top: number; children: React.ReactNode; gap?: number; style?: React.CSSProperties }> = ({ top, children, gap = 0, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", alignItems: "center", gap, ...style }}>{children}</div>
);
const Burst: React.FC<{ t: number; at: number; y: number; c?: string }> = ({ t, at, y, c = WHITE }) => {
  if (t < at || t > at + 0.8) return null;
  const u = lin(t, at, at + 0.7);
  return <div style={{ position: "absolute", left: 540 - 450, top: y - 450, width: 900, height: 900, borderRadius: "50%", border: `${(16 * (1 - u)).toFixed(1)}px solid ${c}`, opacity: 0.8 * (1 - u), transform: `scale(${(0.35 + 0.9 * u).toFixed(3)})` }} />;
};
const money = (v: number) => "R$ " + Math.floor(v).toLocaleString("pt-BR") + "," + String(Math.round((v % 1) * 100)).padStart(2, "0");

// 0–2.0: ÚLTIMA / CHANCE
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.hook;
  const at = 0.49;
  const shake = t > at && t < at + 0.25 ? Math.sin(t * 90) * 9 * (1 - lin(t, at, at + 0.25)) : 0;
  return (
    <MScene t={t} a={a} b={b} bg="red" cam="in">
      <AbsoluteFill style={{ transform: `translate(${shake.toFixed(1)}px, ${(-shake * 0.6).toFixed(1)}px)` }}>
        <Row top={600}><div style={slam(t, 0.11, 0.22)}><div style={{ ...it(210), textShadow: `8px 8px 0 ${DARK_RED}` }}>Última</div></div></Row>
        <Row top={850} style={slam(t, at, 0.24)}>
          <div style={{ background: WHITE, padding: "18px 60px 26px", transform: "skewX(-10deg)", boxShadow: `14px 14px 0 ${INK}, 0 24px 60px rgba(0,0,0,0.4)` }}>
            <div style={{ ...it(170, RED), transform: "skewX(10deg)" }}>Chance</div>
          </div>
        </Row>
        <Row top={1170}><Line t={t} at={0.85} w="de garantir sua matrícula" size={56} /></Row>
      </AbsoluteFill>
    </MScene>
  );
};

// 2.0–3.72: BLACK / FALCON / ACADEMIA
const Brand: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.brand;
  return (
    <MScene t={t} a={a} b={b} bg="black" cam="out">
      <Row top={620}><div style={slam(t, 2.19, 0.24)}><div style={{ ...it(250), letterSpacing: "0.02em" }}>Black</div></div></Row>
      <Row top={900}><Tag t={t} at={2.63} w="Falcon" size={170} bg={RED} fg={WHITE} shadow={WHITE} /></Row>
      <Row top={1190}><Line t={t} at={3.02} w="Academia" size={84} /></Row>
    </MScene>
  );
};

// 5.1–7.68: 12X DE R$ 84,90
const Price: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.price;
  const at = 6.3;
  return (
    <MScene t={t} a={a} b={b} bg="dark" cam="right">
      <Row top={430}>
        <div style={{ ...it(46), border: `4px solid ${WHITE}`, borderRadius: 14, padding: "12px 26px 14px", opacity: k(t, a + 0.04, 0.3), transform: `translateY(${((1 - k(t, a + 0.04, 0.35)) * -40).toFixed(1)}px)` }}>Plano anual</div>
      </Row>
      <Row top={570}><div style={slam(t, 5.24, 0.26)}><div style={{ ...it(200), textShadow: `8px 8px 0 ${INK}` }}>12x de</div></div></Row>
      <Row top={830} gap={14} style={{ ...slam(t, at, 0.3), alignItems: "flex-start" }}>
        <div style={{ ...it(76), marginTop: 30, textShadow: `5px 5px 0 ${INK}` }}>R$</div>
        <div style={{ ...it(215), letterSpacing: "-0.04em", textShadow: `8px 8px 0 ${INK}, 0 0 50px rgba(0,0,0,0.5)` }}>84,90</div>
      </Row>
      <Row top={1160}><Tag t={t} at={6.95} w="por mês" size={96} /></Row>
      <Burst t={t} at={at} y={940} />
    </MScene>
  );
};

// 7.68–14.72: MENSAL x ANUAL (barras que se desenham, valores contando)
const Cmp: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.cmp;
  const g1 = interpolate(t, [9.3, 10.5], [0, 1], { ...cl, easing: Easing.out(Easing.cubic) });
  const g2 = interpolate(t, [13.4, 14.3], [0, 1], { ...cl, easing: Easing.out(Easing.cubic) });
  const R = 1018.8 / 1858.8;
  const block = (top: number, label: string, labelAt: number, color: string, g: number, full: number, value: number) => (
    <div style={{ position: "absolute", left: 120, width: COL, top, opacity: k(t, labelAt, 0.3), transform: `translateY(${((1 - k(t, labelAt, 0.4)) * 40).toFixed(1)}px)` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 22 }}>
        <div style={it(54, color === RED ? RED : INK)}>{label}</div>
        <div style={{ ...it(70, INK), fontVariantNumeric: "tabular-nums", opacity: g > 0 ? 1 : 0 }}>{money(value * g)}</div>
      </div>
      <div style={{ height: 130, borderRadius: 18, background: "#E3DCD6", overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${(full * g * 103).toFixed(2)}%`, background: color, borderRadius: 18, transform: "skewX(-10deg)", transformOrigin: "0 0", marginLeft: -12 }} />
      </div>
    </div>
  );
  // câmera estilo Screen Studio: visão geral → aproxima na barra do mensal → desce para a do anual → volta ao geral
  const c1 = k(t, 9.0, 0.6), c2 = k(t, 11.95, 0.55), c3 = k(t, 14.05, 0.5);
  const S = 1 + 0.14 * c1 - 0.17 * c3 + 0.03 * lin(t, 9.6, 14.05);
  const Y = 960 + (880 - 960) * c1 + (1200 - 880) * c2 + (960 - 1200) * c3;
  return (
    <MScene t={t} a={a} b={b} bg="paper" cam="none">
      <AbsoluteFill style={{ transform: `translateY(${(-(Y - 960) * S).toFixed(1)}px) scale(${S.toFixed(4)})` }}>
        <Row top={540}><Line t={t} at={7.74} w="Em 12 meses" size={96} color={INK} shadow={false} /></Row>
        {block(770, "Mensal", 7.84, "#2A2A2A", g1, 1, 1858.8)}
        {block(1130, "Plano anual", 8.1, RED, g2, R, 1018.8)}
      </AbsoluteFill>
    </MScene>
  );
};

// 14.72–18.08: ECONOMIA DE R$ 840 / + DE 5 MENSALIDADES
const Eco: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.eco;
  const at = 15.7;
  const v = Math.round(840 * interpolate(t, [at, at + 0.55], [0, 1], { ...cl, easing: Easing.out(Easing.cubic) }));
  return (
    <MScene t={t} a={a} b={b} bg="red" cam="tilt">
      <Row top={500}><Line t={t} at={14.8} w="Você economiza" size={90} /></Row>
      <Row top={660} gap={16} style={{ ...slam(t, at, 0.3), alignItems: "flex-start" }}>
        <div style={{ ...it(100), marginTop: 40, textShadow: `6px 6px 0 ${DARK_RED}` }}>R$</div>
        <div style={{ ...it(300), letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums", textShadow: `10px 10px 0 ${DARK_RED}` }}>{v}</div>
      </Row>
      <Row top={1070}><Tag t={t} at={16.8} w="+ de 5 mensalidades" size={66} shadow={INK} /></Row>
      <Row top={1270} gap={26}>
        {[0, 1, 2, 3, 4].map((i) => (
          <div key={i} style={{ width: 120, height: 130, borderRadius: 16, background: WHITE, overflow: "hidden", boxShadow: `6px 6px 0 ${DARK_RED}`, transform: `scale(${pop(t, 17.0 + i * 0.1, 0.35).toFixed(3)})` }}>
            <div style={{ height: 34, background: INK }} />
            <svg width={120} height={96} viewBox="0 0 24 19"><path d="M6.5 10l3.6 3.6L17.5 6" fill="none" stroke={RED} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" /></svg>
          </div>
        ))}
      </Row>
      <Burst t={t} at={at} y={830} />
    </MScene>
  );
};

// 19.95–21.38: SÓ ATÉ / 30 NOVEMBRO / ÚLTIMA CHANCE
const DateSc: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = MS.date;
  const inn = pop(t, a + 0.02, 0.45);
  return (
    <MScene t={t} a={a} b={b} bg="dark" cam="in">
      <Row top={460}><Line t={t} at={a + 0.02} w="Só até" size={90} /></Row>
      <div style={{ position: "absolute", left: 540 - 240, top: 600, width: 480, height: 520, borderRadius: 30, background: WHITE, overflow: "hidden", boxShadow: `14px 14px 0 ${RED}, 0 30px 60px rgba(0,0,0,0.5)`, transform: `scale(${inn.toFixed(3)}) rotate(${(-6 + 6 * k(t, a, 0.6)).toFixed(1)}deg)` }}>
        <div style={{ height: 130, background: RED, display: "flex", alignItems: "center", justifyContent: "center" }}><div style={it(62)}>Novembro</div></div>
        <div style={{ height: 390, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ ...slam(t, 20.38, 0.26) }}><div style={{ ...it(280, INK), letterSpacing: "-0.04em", marginLeft: -16 }}>30</div></div>
        </div>
      </div>
      <Row top={1240}><Tag t={t} at={20.75} w="Última chance" size={84} /></Row>
    </MScene>
  );
};

// 23.9–fim: BLACK FALCON / logo / AGENDE AGORA
const Fim: React.FC<{ t: number }> = ({ t }) => {
  const [a] = MS.fim;
  const e = pop(t, 24.75, 0.6);
  const press = 1 - 0.07 * Math.max(0, 1 - Math.abs(t - 27.2) / 0.12);
  const ring = lin(t, 27.2, 27.9);
  return (
    <MScene t={t} a={a} b={END} bg="dark" cam="out">
      <Row top={400} gap={26}>
        <div style={slam(t, 23.98, 0.24)}><div style={{ ...it(92), textShadow: `6px 6px 0 ${INK}` }}>Black</div></div>
        <Tag t={t} at={24.3} w="Falcon" size={92} bg={RED} fg={WHITE} shadow={WHITE} />
      </Row>
      <div style={{ position: "absolute", left: 90, right: 90, top: 560, height: 440, borderRadius: "50%", background: "radial-gradient(ellipse at center, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.7) 45%, rgba(0,0,0,0) 72%)", opacity: Math.min(1, e * 2) }} />
      <Row top={640} style={{ opacity: Math.min(1, e * 2), transform: `scale(${e.toFixed(3)})` }}>
        <Img src={staticFile("josiane/logo-completo.png")} style={{ width: 760, display: "block", filter: "drop-shadow(0 18px 40px rgba(0,0,0,0.6))" }} />
      </Row>
      <Row top={1010}><Line t={t} at={25.35} w="Academia Fitness" size={64} /></Row>
      <Row top={1200} style={{ transform: `scale(${(pop(t, 26.27, 0.45) * press).toFixed(3)})` }}>
        <div style={{ position: "relative" }}>
          {t > 27.2 ? <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `6px solid ${WHITE}`, opacity: 1 - ring, transform: `scale(${(1 + ring * 0.3).toFixed(3)})` }} /> : null}
          <div style={{ background: WHITE, borderRadius: 999, padding: "26px 70px 30px", boxShadow: `0 18px 44px rgba(0,0,0,0.5), 0 10px 0 ${RED}` }}>
            <div style={it(84, RED)}>Agende agora</div>
          </div>
        </div>
      </Row>
      <Row top={1410}><Line t={t} at={26.75} w="Sua aula experimental grátis" size={50} /></Row>
    </MScene>
  );
};

// ───────── trocas: nunca a mesma duas vezes seguidas ─────────
type TK = "iris" | "flash" | "stripe" | "split" | "redflash";
const TR: [number, TK, string][] = [
  [2.0, "iris", "#050505"], [3.72, "flash", WHITE], [5.1, "stripe", RED], [7.68, "split", PAPER], [14.72, "iris", RED],
  [18.08, "flash", WHITE], [19.95, "stripe", RED], [21.38, "redflash", RED], [23.9, "split", "#0A0A0A"],
];
const Trans: React.FC<{ t: number; at: number; kind: TK; c: string; i: number }> = ({ t, at, kind, c, i }) => {
  const d = 0.2;
  if (t < at - d || t > at + d + 0.1) return null;
  if (kind === "flash" || kind === "redflash") {
    if (t < at) return null;
    return <AbsoluteFill style={{ background: c, opacity: 0.85 * (1 - lin(t, at, at + 0.28)) }} />;
  }
  if (kind === "iris") {
    // a cor da cena seguinte nasce no centro e cobre a tela
    return t < at ? <div style={{ position: "absolute", left: 540 - 1300, top: 960 - 1300, width: 2600, height: 2600, borderRadius: 1300, background: c, boxShadow: `0 0 0 14px ${WHITE}`, transform: `scale(${interpolate(t, [at - d, at], [0, 1], { ...cl, easing: Easing.in(Easing.quad) }).toFixed(4)})` }} /> : null;
  }
  if (kind === "split") {
    const v = t < at ? interpolate(t, [at - d, at], [0, 1], { ...cl, easing: OUT }) : 1 - interpolate(t, [at, at + d], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
    return (
      <>
        <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 962, background: c, borderBottom: `10px solid ${RED}`, boxSizing: "border-box", transform: `translateY(${((v - 1) * 980).toFixed(0)}px)` }} />
        <div style={{ position: "absolute", left: 0, top: 958, width: 1080, height: 962, background: c, borderTop: `10px solid ${RED}`, boxSizing: "border-box", transform: `translateY(${((1 - v) * 980).toFixed(0)}px)` }} />
      </>
    );
  }
  const dir = i % 2 ? -1 : 1;
  const x = (lin(t, at - d, at + d) * 2 - 1) * 2100 * dir;
  return <div style={{ position: "absolute", left: 540 - 800, top: -300, width: 1600, height: 2520, transform: `translateX(${x.toFixed(0)}px) skewX(${-16 * dir}deg)`, background: c, boxShadow: `${110 * dir}px 0 0 ${WHITE}, ${-110 * dir}px 0 0 ${DARK_RED}` }} />;
};

